INSERT INTO categories (category_id, name, description) VALUES
    (1, 'Masks & Snorkels', 'Masks, snorkels, and accessories for clear underwater vision.'),
    (2, 'Regulators & Air', 'Breathing regulators, gauges, and cylinder accessories.'),
    (3, 'Buoyancy & Exposure', 'Buoyancy compensators and thermal protection.'),
    (4, 'Fins & Boots', 'Fins, boots, and gear for efficient movement in the water.'),
    (5, 'Dive Computers & Instruments', 'Computers and instruments for dive planning and monitoring.'),
    (6, 'Safety & Surface Gear', 'Surface signaling, cutting tools, and diver safety equipment.');
INSERT INTO products (product_id, sku, name, description, category_id, unit_price, currency, stock_quantity, reorder_level, is_active, created_at, updated_at) VALUES
    (1, 'MASK-001', 'Low-volume dive mask', 'Low-volume tempered-glass mask with a soft silicone skirt.', 1, 74.95, 'CAD', 14, 5, TRUE, '2025-09-01 00:00:00+00', '2026-07-11 14:51:27+00'),
    (2, 'MASK-002', 'Wide-view dive mask', 'Wide-angle lens design for an expanded field of view.', 1, 89.50, 'CAD', 24, 5, TRUE, '2025-09-01 00:00:00+00', '2026-09-01 06:00:00+00'),
    (3, 'MASK-003', 'Frameless travel mask', 'Lightweight frameless mask that packs easily for travel.', 1, 99.00, 'CAD', 31, 5, TRUE, '2025-09-01 00:00:00+00', '2026-06-27 22:32:02+00'),
    (4, 'SNORK-001', 'Flexible-top snorkel', 'Flexible snorkel with a comfortable silicone mouthpiece.', 1, 34.95, 'CAD', 9, 5, TRUE, '2025-09-01 00:00:00+00', '2026-09-24 15:09:55+00'),
    (5, 'MASK-004', 'Prescription-ready mask', 'Durable mask designed to accept compatible prescription lenses.', 1, 119.00, 'CAD', 23, 5, TRUE, '2025-09-01 00:00:00+00', '2026-06-03 21:31:27+00'),
    (6, 'REG-001', 'Balanced diaphragm first stage', 'Environmentally sealed first stage for cold-water diving.', 2, 429.00, 'CAD', 4, 3, TRUE, '2025-09-01 00:00:00+00', '2026-08-28 15:02:41+00'),
    (7, 'REG-002', 'Adjustable second stage', 'Compact second stage with user-adjustable breathing resistance.', 2, 289.95, 'CAD', 19, 5, TRUE, '2025-09-01 00:00:00+00', '2026-09-05 23:01:48+00'),
    (8, 'REG-003', 'Alternate air source', 'High-visibility alternate second stage for buddy breathing.', 2, 159.00, 'CAD', 12, 5, TRUE, '2025-09-01 00:00:00+00', '2026-08-13 17:50:56+00'),
    (9, 'GAUGE-001', 'Compact pressure gauge', 'Easy-to-read analog submersible pressure gauge.', 2, 109.50, 'CAD', 28, 5, TRUE, '2025-09-01 00:00:00+00', '2026-05-26 19:57:11+00'),
    (10, 'HOSE-001', 'Braided regulator hose', 'Flexible high-pressure hose for compatible dive regulators.', 2, 64.95, 'CAD', 27, 5, TRUE, '2025-09-01 00:00:00+00', '2026-07-01 06:00:00+00'),
    (11, 'BCD-001', 'Back-inflate buoyancy compensator', 'Streamlined back-inflate BCD with integrated weight pockets.', 3, 649.00, 'CAD', 4, 3, TRUE, '2025-09-01 00:00:00+00', '2025-09-01 11:00:00+00'),
    (12, 'BCD-002', 'Travel buoyancy compensator', 'Lightweight travel BCD with fold-flat construction.', 3, 529.00, 'CAD', 5, 3, TRUE, '2025-09-01 00:00:00+00', '2026-07-08 20:15:05+00'),
    (13, 'SUIT-001', '3 mm full wetsuit', 'Stretch neoprene full suit for warm-water diving.', 3, 279.95, 'CAD', 23, 5, TRUE, '2025-09-01 00:00:00+00', '2026-07-18 18:41:00+00'),
    (14, 'SUIT-002', '5 mm hooded wetsuit', 'Thermal full suit with an integrated hood for cooler water.', 3, 459.00, 'CAD', 23, 3, TRUE, '2025-09-01 00:00:00+00', '2026-07-16 16:02:04+00'),
    (15, 'GLOVE-001', 'Neoprene dive gloves', 'Textured neoprene gloves for warmth and grip.', 3, 59.95, 'CAD', 8, 5, TRUE, '2025-09-01 00:00:00+00', '2026-07-19 20:35:56+00'),
    (16, 'FIN-001', 'Open-heel paddle fins', 'Responsive paddle fins for travel and recreational diving.', 4, 189.00, 'CAD', 5, 5, TRUE, '2025-09-01 00:00:00+00', '2026-09-20 13:44:01+00'),
    (17, 'FIN-002', 'Split-blade open-heel fins', 'Efficient split-blade fins with adjustable spring straps.', 4, 219.95, 'CAD', 24, 5, TRUE, '2025-09-01 00:00:00+00', '2026-08-14 23:24:23+00'),
    (18, 'FIN-003', 'Full-foot snorkeling fins', 'Comfortable full-foot fins for snorkeling and warm-water use.', 4, 99.00, 'CAD', 6, 5, TRUE, '2025-09-01 00:00:00+00', '2026-09-11 15:34:56+00'),
    (19, 'BOOT-001', '5 mm neoprene dive boots', 'Reinforced-sole boots for shore entries and cold water.', 4, 89.95, 'CAD', 28, 5, TRUE, '2025-09-01 00:00:00+00', '2026-07-03 13:42:19+00'),
    (20, 'FIN-004', 'Compact travel fins', 'Short-blade fins that fit easily into a travel bag.', 4, 129.00, 'CAD', 21, 5, TRUE, '2025-09-01 00:00:00+00', '2026-06-19 21:09:31+00'),
    (21, 'COMP-001', 'Wrist dive computer', 'Nitrox-capable wrist computer with a clear high-contrast display.', 5, 389.00, 'CAD', 5, 3, TRUE, '2025-09-01 00:00:00+00', '2026-05-26 19:57:11+00'),
    (22, 'COMP-002', 'Air-integrated dive computer', 'Wireless air integration with customizable dive alarms.', 5, 849.00, 'CAD', 17, 3, TRUE, '2025-09-01 00:00:00+00', '2026-05-07 00:53:37+00'),
    (23, 'COMP-003', 'Console dive computer', 'Rugged console computer with compass and pressure gauge.', 5, 579.00, 'CAD', 4, 3, TRUE, '2025-09-01 00:00:00+00', '2025-09-01 23:00:00+00'),
    (24, 'COMP-004', 'Wrist compass', 'Luminous underwater compass with a rotating bezel.', 5, 119.95, 'CAD', 8, 5, TRUE, '2025-09-01 00:00:00+00', '2026-02-17 18:10:56+00'),
